// The video reads only two inputs, both at bundle time:
//   video/storyboard.json  (scene timings, shared with the audio track)
//   video/metrics.json     (numbers and labels from the real system; copied to src/generated by render.mjs)
// plus the optional app captures listed in src/generated/captures.json.
import storyboard from "../../storyboard.json";
import metricsJson from "./generated/metrics.json";
import capturesJson from "./generated/captures.json";

export type Scene = { id: string; start: number; end: number; beat: string; audio: string };
export const SB = storyboard as {
  fps: number; width: number; height: number; max_seconds: number; title: string; tagline: string; scenes: Scene[];
};
export const M: any = metricsJson;
export const CAP: any = capturesJson;

export const sceneFrames = (s: Scene) => ({ from: Math.round(s.start * SB.fps), dur: Math.round((s.end - s.start) * SB.fps) });
export const TOTAL_FRAMES = Math.round(SB.scenes[SB.scenes.length - 1].end * SB.fps);

export const hasShot = (name: string) => Boolean(CAP?.available && CAP.shots?.[name]);
export const shot = (name: string) => CAP?.shots?.[name];
